for _ in range(int(input())):
	n = int(input())
	a = list(map(int, input().split()))
	suf = 0
	pref = 0
	mxpref = 0
	for i in range(n):
		if i % 2 == 0:
			suf += a[i]
		else:
			suf -= a[i]
	ans = suf
	for i in range(n):
		if i % 2 == 0:
			suf -= a[i]
			pref += a[i]
		else:
			suf += a[i]
			pref -= a[i]
		if i % 2 != n % 2:
			ans = max(ans, pref - suf)
			mxpref = max(mxpref, pref)
		else:
			ans = max(ans, 2 * mxpref - pref - suf)
	print(ans)
